// Google Earth Engine (GEE) JavaScript Code to Extract Mumbai Flood Extent
var mumbai = ee.Geometry.Rectangle([72.75, 18.85, 73.05, 19.35]);

// Load Sentinel-1 SAR GRD
var s1 = ee.ImageCollection('COPERNICUS/S1_GRD')
  .filterBounds(mumbai)
  .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
  .filter(ee.Filter.eq('instrumentMode', 'IW'));

// Pre-flood & Flood periods
var before = s1.filterDate('2024-05-01', '2024-05-30').select('VH').mosaic().clip(mumbai);
var after = s1.filterDate('2024-07-05', '2024-07-15').select('VH').mosaic().clip(mumbai);

// Difference for water accumulation
var diff = after.subtract(before);
var flooded = diff.lt(-3.0).and(after.lt(-18.0));

Map.centerObject(mumbai, 11);
Map.addLayer(flooded.updateMask(flooded), {palette: 'cyan'}, 'Flooded Inundation Areas');
